python3 -I -c 'exec('"'"'import json, statistics as S, sys
W = sys.argv[1] if len(sys.argv) > 1 else "study/results/removal_sample/runs"
names = [l.split("\t")[0] for l in open(W + "/pkgs24.tsv") if l.strip()]
def ld(d):
    try:
        return json.load(open(W + "/mig/" + d + "/summary.json"))
    except OSError:
        return None
def un(n):
    return next((s for s in (ld(p + n) for p in ("s2_", "c2_", "s_")) if s), None)
for lab, get in (("v14 defaults", lambda n: ld("v14_" + n)), ("no budget", un)):
    r = []
    for n in names:
        s = get(n)
        if s is None:
            continue
        t0, t1, db = s.get("time0") or {}, s.get("time1") or {}, s.get("default_build") or {}
        timed = bool(s.get("affected_modules")) and t0.get("rc") == 0 and t1.get("rc") == 0 and bool(t0.get("n_built"))
        r.append((n, s["native_axioms_before"], s["native_axioms_after"], timed, t0.get("wall"), t1.get("wall"), bool(s.get("build_ok")) and db.get("rc") == 0))
    a0, a1 = sum(x[1] for x in r), sum(x[2] for x in r)
    med = S.median([(x[1] - x[2]) / x[1] for x in r if x[1]])
    tm = [x for x in r if x[3] and x[4]]
    w = max(tm, key=lambda x: x[5] / x[4])
    print(f"{lab}: {len(r)} packages; native axioms removed {100 * (a0 - a1) / a0:.1f}% ({a0 - a1}/{a0}), median {100 * med:.1f}%; median wall ratio {S.median([x[5] / x[4] for x in tm]):.2f}; worst {w[5] / w[4]:.2f} ({w[0]}, {w[4]:.2f} -> {w[5]:.2f} s); more than twice as slow and 5 s longer: {sum(1 for x in tm if x[5] / x[4] > 2 and x[5] - x[4] > 5)} of {len(tm)}; builds ok {sum(1 for x in r if x[6])} of {len(r)}")
'"'"')'; grep '^| \*\*v14, defaults' study/results/removal_sample/budget_table.md | cut -d'|' -f2,6,7,12,13,14; sed -n '/^`migrate` rewrites/,/^$/p' README.md | tr '
' ' ' | tr -s ' ' | grep -o 'random sample of 24 packages with 1,472 native axioms\|the defaults removed 30% of them (median 25% per package), and no package.s build took more than 1.7 times as long (the slowest went from 1.03 to 1.74 s)\|it removed 54% (median 76%), but build time rose by a median factor of 1.9, and by up to 143.5 times\|In both runs 23 packages built afterwards'

python3 -I -B -c 'exec('"'"'import os, re
def arg(s, i):
    d = 0
    for j in range(i, len(s)):
        if s[j] == '"'"'{'"'"':
            d += 1
        elif s[j] == '"'"'}'"'"':
            d -= 1
            if d == 0:
                return s[i + 1:j]
    return s[i + 1:]
sec = sub = tab = 0
app = intab = False
cur = None
lab, title = {}, {}
for raw in open('"'"'paper/main.tex'"'"', encoding='"'"'utf-8'"'"'):
    s = re.sub(r'"'"'(?<!\\)%.*'"'"', '"'"''"'"', raw)
    if s.strip() == '"'"'\\appendix'"'"':
        app, sec = True, 0
    for m in re.finditer(r'"'"'\\(section|subsection|caption)\{|\\begin\{table\*?\}|\\end\{table\*?\}|\\label\{([^}]*)\}'"'"', s):
        k = m.group(0)
        if k.startswith('"'"'\\begin'"'"'):
            intab = True
        elif k.startswith('"'"'\\end'"'"'):
            intab = False
        elif m.group(1) == '"'"'section'"'"':
            sec, sub = sec + 1, 0
            cur = ('"'"'Appendix'"'"', chr(64 + sec)) if app else ('"'"'Section'"'"', str(sec))
            title[cur] = arg(s, m.end() - 1)
        elif m.group(1) == '"'"'subsection'"'"':
            sub += 1
            cur = ('"'"'Section'"'"', '"'"'%d.%d'"'"' % (sec, sub))
            title[cur] = arg(s, m.end() - 1)
        elif m.group(1) == '"'"'caption'"'"':
            if intab:
                tab += 1
                cur = ('"'"'Table'"'"', str(tab))
                title[cur] = arg(s, m.end() - 1)
        elif m.group(2) and m.group(2).split('"'"':'"'"')[0] in ('"'"'sec'"'"', '"'"'tab'"'"', '"'"'app'"'"') and cur:
            lab[cur] = m.group(2)
N = r'"'"'(?:[0-9]+(?:\.[0-9]+)*|[A-Z](?![A-Za-z])(?:\.[0-9]+)*)'"'"'
pat = re.compile(r'"'"'\b(Tables?|Sections?|Appendix|Appendices) ('"'"' + N + r'"'"'(?:(?:, | and |--|-| to )'"'"' + N + r'"'"')*)( \("([^"]*)"\))?'"'"')
named = re.compile(r'"'"'\bSections? "([^"]*)"'"'"')
kinds = {'"'"'Tables'"'"': '"'"'Table'"'"', '"'"'Sections'"'"': '"'"'Section'"'"', '"'"'Appendices'"'"': '"'"'Appendix'"'"'}
files = sorted(os.path.relpath(os.path.join(d, f)) for d, _, fs in os.walk('"'"'.'"'"') for f in fs if f.endswith('"'"'.md'"'"'))
n = 0
for f in files:
    for i, line in enumerate(open(f, encoding='"'"'utf-8'"'"'), 1):
        for m in pat.finditer(line):
            k = kinds.get(m.group(1), m.group(1))
            parts = re.split(r'"'"'(, | and |--|-| to )'"'"', m.group(2))
            nums = []
            for j in range(0, len(parts), 2):
                x = parts[j]
                if j and parts[j - 1] in ('"'"'-'"'"', '"'"'--'"'"', '"'"' to '"'"') and nums:
                    a = nums[-1]
                    pa, pb = a.rpartition('"'"'.'"'"'), x.rpartition('"'"'.'"'"')
                    if pa[0] == pb[0] and pa[2].isdigit() and pb[2].isdigit():
                        nums += [(pa[0] + '"'"'.'"'"' if pa[0] else '"'"''"'"') + str(v) for v in range(int(pa[2]) + 1, int(pb[2]) + 1)]
                        continue
                nums.append(x)
            for x in nums:
                n += 1
                t = (k, x)
                out = lab.get(t) or ('"'"'(%s)'"'"' % title[t] if t in title else '"'"'(no such %s)'"'"' % k.lower())
                if m.group(4) is not None and x == nums[-1]:
                    q = m.group(4)
                    out += '"'"' "%s" %s'"'"' % (q, '"'"'title OK'"'"' if title.get(t) == q else '"'"'title MISMATCH: %s'"'"' % title.get(t))
                print('"'"'%s:%d: %s %s = %s'"'"' % (f, i, k, x, out))
        for m in named.finditer(line):
            n += 1
            hit = [x for (k, x), v in title.items() if k == '"'"'Section'"'"' and v == m.group(1)]
            print('"'"'%s:%d: Section "%s" = %s'"'"' % (f, i, m.group(1), hit[0] if hit else '"'"'(no such section)'"'"'))
print('"'"'markdown files: %d; pointers: %d'"'"' % (len(files), n))
'"'"')'
